import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('balanceDue returns total when no payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  assert.equal(balanceDue(issued), totals.total);
});

test('balanceDue returns reduced balance after payment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const half = Math.floor(totals.total / 2);
  const paid = recordPayment(issued, { amount: half, date: '2025-10-08' }).value;
  assert.equal(balanceDue(paid), totals.total - half);
});

test('balanceDue returns 0 when fully paid', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2025-10-08' }).value;
  assert.equal(balanceDue(paid), 0);
});

test('recordPayment rejects draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  }).value;
  const result = recordPayment(invoice, { amount: 100, date: '2025-10-08' });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_ISSUED');
});

test('recordPayment rejects non-integer amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const result = recordPayment(issued, { amount: 100.5, date: '2025-10-08' });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('recordPayment rejects zero amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const result = recordPayment(issued, { amount: 0, date: '2025-10-08' });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('recordPayment rejects negative amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const result = recordPayment(issued, { amount: -100, date: '2025-10-08' });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('recordPayment rejects overpayment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const result = recordPayment(issued, { amount: totals.total + 1, date: '2025-10-08' });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'OVERPAYMENT');
});

test('recordPayment returns partially_paid status when balance remains', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const half = Math.floor(totals.total / 2);
  const result = recordPayment(issued, { amount: half, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'partially_paid');
});

test('recordPayment returns paid status when balance is zero', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const result = recordPayment(issued, { amount: totals.total, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('recordPayment includes payment with date', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const result = recordPayment(issued, { amount: 500, date: '2025-10-08' });
  assert.equal(result.value.payments.length, 1);
  assert.equal(result.value.payments[0].amount, 500);
  assert.equal(result.value.payments[0].date, '2025-10-08');
});

test('recordPayment preserves existing payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  assert.equal(issuedResult.ok, true);
  const issued = issuedResult.value;
  const totals = invoiceTotals(issued);
  const third = Math.floor(totals.total / 3);

  const paid1 = recordPayment(issued, { amount: third, date: '2025-10-08' }).value;
  assert.equal(paid1.payments.length, 1);

  const paid2 = recordPayment(paid1, { amount: third, date: '2025-10-09' }).value;
  assert.equal(paid2.payments.length, 2);
  assert.equal(paid2.payments[0].amount, third);
  assert.equal(paid2.payments[1].amount, third);
});

test('recordPayment does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  assert.equal(issuedResult.ok, true);
  const issued = issuedResult.value;
  const original = JSON.stringify(issued);
  recordPayment(issued, { amount: 100, date: '2025-10-08' });
  assert.equal(JSON.stringify(issued), original);
});

test('recordPayment accepts payment on partially_paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  assert.equal(issuedResult.ok, true);
  const issued = issuedResult.value;
  const totals = require('../src/invoices.js').invoiceTotals(issued);
  const half = Math.floor(totals.total / 2);

  const paid1 = recordPayment(issued, { amount: half, date: '2025-10-08' }).value;
  assert.equal(paid1.status, 'partially_paid');

  const result = recordPayment(paid1, { amount: half, date: '2025-10-09' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('balanceDue handles missing payments array', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    number: 'INV-2025-0001',
    status: 'issued',
    lines: [
      {
        sku: 'SKU-001',
        name: 'Gadget',
        qty: 1,
        unitPrice: 1000,
        vatRate: 21,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(balanceDue(invoice), totals.total);
});

test('recordPayment creates payments array if missing', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    number: 'INV-2025-0001',
    status: 'issued',
    lines: [
      {
        sku: 'SKU-001',
        name: 'Gadget',
        qty: 1,
        unitPrice: 1000,
        vatRate: 21,
      },
    ],
  };
  const result = recordPayment(invoice, { amount: 500, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.payments.length, 1);
});

test('recordPayment rejects overpayment on partially paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  assert.equal(issuedResult.ok, true);
  const issued = issuedResult.value;
  const totals = invoiceTotals(issued);
  const half = Math.floor(totals.total / 2);

  const paid1 = recordPayment(issued, { amount: half, date: '2025-10-08' }).value;
  const remaining = balanceDue(paid1);

  const result = recordPayment(paid1, { amount: remaining + 1, date: '2025-10-09' });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'OVERPAYMENT');
});

test('recordPayment preserves all invoice data', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'SKU-001', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  assert.equal(issuedResult.ok, true);
  const issued = issuedResult.value;
  const result = recordPayment(issued, { amount: 100, date: '2025-10-08' });
  assert.equal(result.ok, true);
  const paid = result.value;

